void Ads::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Post("/ad_accounts/{ad_account_id}/ad_previews", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdadPreviewsPostRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/ads/targeting_analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdadstargetingAnalyticsGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/ads/analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdadsanalyticsGetRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/ads", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdadsPostRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/ads/{ad_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdadsadIdGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/ads", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdadsGetRequest(req, res, auth);
    });
    svr.Patch("/ad_accounts/{ad_account_id}/ads", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdadsPatchRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/campaign_ad_preview", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignAdPreviewPostRequest(req, res, auth);
    });
    svr.Delete("/ad_accounts/{ad_account_id}/campaign_ad_preview", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignAdPreviewDeleteRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/campaign_ad_preview", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignAdPreviewGetRequest(req, res, auth);
    });
}

